async function fetchWithRetry(url, options = {}, maxRetries = 3, timeoutMs = 10000) {
  let lastError;
  for (let attempt = 0; attempt < maxRetries; attempt++) {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), timeoutMs);
    try {
      const res = await fetch(url, { ...options, signal: controller.signal });
      clearTimeout(timer);
      if (!res.ok) throw new Error(`HTTP ${res.status}: ${res.statusText}`);
      return await res.json();
    } catch (err) {
      clearTimeout(timer);
      lastError = err;
      if (attempt < maxRetries - 1) {
        await new Promise(r => setTimeout(r, Math.pow(2, attempt) * 500));
      }
    }
  }
  throw new Error(`fetchWithRetry failed after ${maxRetries} attempts: ${lastError.message}`);
}

function buildQueryString(params, skipNulls = true) {
  const entries = Object.entries(params).flatMap(([k, v]) => {
    if (skipNulls && (v === null || v === undefined)) return [];
    if (Array.isArray(v)) return v.map(item => [k, item]);
    return [[k, v]];
  });
  if (!entries.length) return '';
  return '?' + new URLSearchParams(entries.map(([k,v]) => [k, String(v)])).toString();
}

function createApiClient(baseURL: string, getToken: () => string | null = () => null, onUnauthorized: () => void = () => {}) {
  const request = async (method: string, path: string, data?: any, extraHeaders: Record<string,string> = {}) => {
    const token = getToken();
    const headers: Record<string,string> = {
      'Content-Type': 'application/json',
      'Accept': 'application/json',
      ...extraHeaders
    };
    if (token) headers['Authorization'] = `Bearer ${token}`;
    const opts: RequestInit = { method, headers };
    if (data !== undefined) opts.body = JSON.stringify(data);
    const res = await fetchWithRetry(`${baseURL}${path}`, opts);
    if (res.status === 401) { onUnauthorized(); throw new Error('Unauthorized'); }
    return res;
  };
  return {
    get:    (path: string, headers?: any) => request('GET', path, undefined, headers),
    post:   (path: string, data: any) => request('POST', path, data),
    put:    (path: string, data: any) => request('PUT', path, data),
    patch:  (path: string, data: any) => request('PATCH', path, data),
    delete: (path: string) => request('DELETE', path)
  };
}

async function buildGraphQLQuery(endpoint, query, variables = {}, token = null) {
  const headers = { 'Content-Type': 'application/json' };
  if (token) headers['Authorization'] = `Bearer ${token}`;
  const res = await fetch(endpoint, {
    method: 'POST',
    headers,
    body: JSON.stringify({ query, variables })
  });
  const json = await res.json();
  if (json.errors?.length) {
    const msg = json.errors.map(e => e.message).join('; ');
    throw new Error(`GraphQL Error: ${msg}`);
  }
  return json.data;
}

function createWebSocketClient(url, handlers = {}, reconnectIntervalMs = 3000, heartbeatIntervalMs = 30000) {
  let ws, heartbeatTimer, reconnectTimer;
  let connected = false;
  const connect = () => {
    ws = new WebSocket(url);
    ws.onopen = () => {
      connected = true;
      clearTimeout(reconnectTimer);
      handlers.onOpen?.();
      heartbeatTimer = setInterval(() => { if (ws.readyState === WebSocket.OPEN) ws.send(JSON.stringify({ type: 'ping' })); }, heartbeatIntervalMs);
    };
    ws.onmessage = (e) => {
      try { const data = JSON.parse(e.data); if (data.type !== 'pong') handlers.onMessage?.(data); }
      catch { handlers.onMessage?.(e.data); }
    };
    ws.onclose = () => {
      connected = false;
      clearInterval(heartbeatTimer);
      handlers.onClose?.();
      reconnectTimer = setTimeout(connect, reconnectIntervalMs);
    };
    ws.onerror = (err) => handlers.onError?.(err);
  };
  connect();
  return {
    send: (data) => ws?.readyState === WebSocket.OPEN && ws.send(JSON.stringify(data)),
    close: () => { clearTimeout(reconnectTimer); clearInterval(heartbeatTimer); ws?.close(); },
    isConnected: () => connected
  };
}

function setupSSE(url, eventHandlers, withCredentials = false) {
  const source = new EventSource(url, { withCredentials });
  Object.entries(eventHandlers).forEach(([event, handler]) => {
    if (event === 'message') source.onmessage = (e) => handler(JSON.parse(e.data));
    else source.addEventListener(event, (e) => handler(JSON.parse(e.data)));
  });
  source.onerror = (e) => console.error('[SSE] Erreur connexion, reconnexion auto...', e);
  return source;
}

const jwt = require('jsonwebtoken');
function generateJWT(payload, secret = JWT_SECRET, expiresIn = JWT_EXPIRY) {
  return jwt.sign(
    { ...payload, iat: Math.floor(Date.now() / 1000) },
    secret,
    { expiresIn, algorithm: 'HS256' }
  );
}

const jwt = require('jsonwebtoken');
function verifyJWT(token, secret = JWT_SECRET) {
  try {
    return jwt.verify(token, secret, { algorithms: ['HS256'] });
  } catch (err) {
    if (err.name === 'TokenExpiredError') throw new Error('TOKEN_EXPIRED');
    if (err.name === 'JsonWebTokenError') throw new Error('TOKEN_INVALID');
    throw new Error('TOKEN_VERIFICATION_FAILED');
  }
}

const jwt = require('jsonwebtoken');
function refreshAccessToken(refreshToken, refreshSecret = process.env.REFRESH_SECRET) {
  const payload = jwt.verify(refreshToken, refreshSecret, { algorithms: ['HS256'] });
  const { iat, exp, ...userPayload } = payload;
  const newAccessToken = generateJWT(userPayload);
  const newRefreshToken = jwt.sign(userPayload, refreshSecret, { expiresIn: REFRESH_TOKEN_EXPIRY, algorithm: 'HS256' });
  return { accessToken: newAccessToken, refreshToken: newRefreshToken };
}

const crypto = require('crypto');
const OAUTH_ENDPOINTS = {
  google: { auth: 'https://accounts.google.com/o/oauth2/v2/auth', token: 'https://oauth2.googleapis.com/token' },
  github: { auth: 'https://github.com/login/oauth/authorize', token: 'https://github.com/login/oauth/access_token' },
  microsoft: { auth: 'https://login.microsoftonline.com/common/oauth2/v2.0/authorize', token: 'https://login.microsoftonline.com/common/oauth2/v2.0/token' }
};
function setupOAuth2Flow(provider, clientId, redirectUri, scopes = ['openid','profile','email']) {
  const codeVerifier = crypto.randomBytes(32).toString('base64url');
  const codeChallenge = crypto.createHash('sha256').update(codeVerifier).digest('base64url');
  const state = crypto.randomBytes(16).toString('hex');
  const ep = OAUTH_ENDPOINTS[provider];
  if (!ep) throw new Error(`Provider OAuth2 inconnu : ${provider}`);
  const params = new URLSearchParams({
    client_id: clientId, redirect_uri: redirectUri,
    response_type: 'code', scope: scopes.join(' '),
    state, code_challenge: codeChallenge, code_challenge_method: 'S256'
  });
  return { authUrl: `${ep.auth}?${params}`, codeVerifier, state };
}

const bcrypt = require('bcrypt');
async function hashPassword(password, rounds = 12) {
  if (!password || password.length < 8) throw new Error('Mot de passe trop court (min 8 chars)');
  return bcrypt.hash(password, rounds);
}

const bcrypt = require('bcrypt');
async function verifyPassword(password, hash) {
  return bcrypt.compare(password, hash);
}

const speakeasy = require('speakeasy');
function generateTOTP(action, secret = null, token = null) {
  if (action === 'secret') {
    const s = speakeasy.generateSecret({ length: 20, name: 'MyApp' });
    return { secret: s.base32, otpauth: s.otpauth_url };
  }
  if (action === 'generate') {
    return speakeasy.totp({ secret, encoding: 'base32' });
  }
  if (action === 'verify') {
    return speakeasy.totp.verify({ secret, encoding: 'base32', token, window: 1 });
  }
  throw new Error('Action TOTP invalide : generate | verify | secret');
}

function authMiddleware(roles = []) {
  return (req, res, next) => {
    const authHeader = req.headers['authorization'];
    if (!authHeader?.startsWith('Bearer ')) return res.status(401).json({ error: 'Token manquant' });
    const token = authHeader.slice(7);
    try {
      const payload = verifyJWT(token);
      req.user = payload;
      if (roles.length && !roles.includes(payload.role)) {
        return res.status(403).json({ error: 'Accès interdit — rôle insuffisant' });
      }
      next();
    } catch (err) {
      const status = err.message === 'TOKEN_EXPIRED' ? 401 : 403;
      res.status(status).json({ error: err.message });
    }
  };
}

const rateLimit = require('express-rate-limit');
const RedisStore = require('rate-limit-redis');
const redis = require('ioredis');
function rateLimitMiddleware(windowMs = RATE_LIMIT_WINDOW_MS, max = RATE_LIMIT_MAX, keyPrefix = 'rl:') {
  const client = new redis(REDIS_URL);
  return rateLimit({
    windowMs, max,
    standardHeaders: true,
    legacyHeaders: false,
    store: new RedisStore({ client, prefix: keyPrefix }),
    handler: (req, res) => res.status(429).json({
      error: 'Trop de requêtes',
      retryAfter: Math.ceil(windowMs / 1000)
    })
  });
}

const cors = require('cors');
function corsMiddleware(origins = CORS_ORIGINS, allowCredentials = true) {
  return cors({
    origin: (origin, cb) => {
      if (!origin || origins.includes(origin)) return cb(null, true);
      cb(new Error(`CORS: Origine non autorisée — ${origin}`));
    },
    credentials: allowCredentials,
    methods: ['GET','POST','PUT','PATCH','DELETE','OPTIONS'],
    allowedHeaders: ['Content-Type','Authorization','X-Request-ID','X-API-Key'],
    exposedHeaders: ['X-Total-Count','X-Page','X-Per-Page']
  });
}

function validateSchema(schema, target = 'body') {
  return (req, res, next) => {
    const data = req[target];
    // Support Zod
    if (typeof schema.safeParse === 'function') {
      const result = schema.safeParse(data);
      if (!result.success) {
        return res.status(422).json({ error: 'Validation échouée', details: result.error.flatten() });
      }
      req[target] = result.data;
      return next();
    }
    // Support Joi
    const { error, value } = schema.validate(data, { abortEarly: false });
    if (error) return res.status(422).json({ error: 'Validation échouée', details: error.details });
    req[target] = value;
    next();
  };
}

const { WebClient } = require('@slack/web-api');
async function sendSlackMessage(channel, text, blocks = null, useWebhook = false) {
  try {
    if (useWebhook) {
      const body = { text, ...(blocks && { blocks }) };
      const res = await fetch(SLACK_WEBHOOK_URL, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) });
      return res.ok;
    }
    const slack = new WebClient(SLACK_BOT_TOKEN);
    const payload = { channel, text, ...(blocks && { blocks }) };
    await slack.chat.postMessage(payload);
    return true;
  } catch (err) {
    console.error('[Slack] Erreur envoi:', err.message);
    return false;
  }
}

function buildSlackAlertBlock(title, message, severity = 'info', actions = []) {
  const icons = { info: 'ℹ️', warning: '⚠️', error: '🚨', success: '✅' };
  const colors = { info: '#0078D4', warning: '#FFA500', error: '#FF0000', success: '#36a64f' };
  const blocks = [
    { type: 'header', text: { type: 'plain_text', text: `${icons[severity] || '📢'} ${title}` } },
    { type: 'section', text: { type: 'mrkdwn', text: message } },
    { type: 'context', elements: [{ type: 'mrkdwn', text: `*Sévérité:* ${severity.toUpperCase()} | *Timestamp:* ${new Date().toISOString()}` }] }
  ];
  if (actions.length) {
    blocks.push({
      type: 'actions',
      elements: actions.map(a => ({ type: 'button', text: { type: 'plain_text', text: a.text }, url: a.url, style: severity === 'error' ? 'danger' : 'primary' }))
    });
  }
  return blocks;
}

async function sendDiscordMessage(content = '', embeds = [], webhookUrl = DISCORD_WEBHOOK_URL) {
  try {
    const res = await fetch(webhookUrl, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ content, embeds, username: 'AlertBot', avatar_url: 'https://i.imgur.com/4M34hi2.png' })
    });
    return res.ok || res.status === 204;
  } catch (err) {
    console.error('[Discord] Erreur envoi:', err.message);
    return false;
  }
}

function buildDiscordEmbed(title, description = '', color = 0x0078D4, fields = [], url = null) {
  return {
    title, description, color,
    ...(url && { url }),
    fields: fields.map(f => ({ name: f.name, value: f.value, inline: f.inline ?? false })),
    footer: { text: `Bot Alerting | ${new Date().toUTCString()}` },
    timestamp: new Date().toISOString()
  };
}

async function sendTeamsMessage(title, body, facts = [], actions = [], webhookUrl = TEAMS_WEBHOOK_URL) {
  const card = {
    type: 'message',
    attachments: [{
      contentType: 'application/vnd.microsoft.card.adaptive',
      content: {
        '$schema': 'http://adaptivecards.io/schemas/adaptive-card.json',
        type: 'AdaptiveCard', version: '1.4',
        body: [
          { type: 'TextBlock', size: 'Large', weight: 'Bolder', text: title },
          { type: 'TextBlock', text: body, wrap: true },
          ...(facts.length ? [{ type: 'FactSet', facts }] : [])
        ],
        actions: actions.map(a => ({ type: 'Action.OpenUrl', title: a.title, url: a.url }))
      }
    }]
  };
  const res = await fetch(webhookUrl, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(card) });
  return res.ok;
}

const twilio = require('twilio');
async function sendSMS(to, message, from = TWILIO_PHONE_FROM) {
  const client = twilio(TWILIO_ACCOUNT_SID, TWILIO_AUTH_TOKEN);
  const msg = await client.messages.create({ body: message, from, to });
  console.log(`[Twilio] SMS envoyé à ${to} | SID: ${msg.sid} | Status: ${msg.status}`);
  return { sid: msg.sid, status: msg.status };
}

const twilio = require('twilio');
async function makeVoiceCall(to, message, language = 'fr-FR') {
  const client = twilio(TWILIO_ACCOUNT_SID, TWILIO_AUTH_TOKEN);
  const twiml = message.startsWith('http') ? undefined : `<Response><Say language="${language}">${message}</Say></Response>`;
  const call = await client.calls.create({
    to, from: TWILIO_PHONE_FROM,
    ...(twiml ? { twiml } : { url: message })
  });
  return { sid: call.sid, status: call.status };
}

const sgMail = require('@sendgrid/mail');
sgMail.setApiKey(SENDGRID_API_KEY);
async function sendEmailSendGrid(to, subject, html = '', templateId = null, templateData = {}, from = 'no-reply@myapp.io', attachments = []) {
  const toArr = Array.isArray(to) ? to : [to];
  const msg = {
    to: toArr, from, subject,
    ...(templateId ? { templateId, dynamicTemplateData: templateData } : { html }),
    ...(attachments.length && { attachments })
  };
  await sgMail.send(msg);
  console.log(`[SendGrid] Email envoyé à ${toArr.join(',')} | Sujet: ${subject}`);
  return true;
}

const nodemailer = require('nodemailer');
async function sendEmailNodmailer(to, subject, html, text = '', from = 'no-reply@myapp.io') {
  const transporter = nodemailer.createTransport({
    host: SMTP_HOST, port: SMTP_PORT, secure: SMTP_PORT === 465,
    auth: { user: process.env.SMTP_USER, pass: process.env.SMTP_PASS },
    tls: { rejectUnauthorized: process.env.NODE_ENV === 'production' }
  });
  const info = await transporter.sendMail({ from, to, subject, html, text: text || html.replace(/<[^>]+>/g,'') });
  console.log(`[Nodemailer] MessageID: ${info.messageId}`);
  return { messageId: info.messageId };
}

const webpush = require('web-push');
webpush.setVapidDetails('mailto:admin@myapp.io', VAPID_PUBLIC_KEY, VAPID_PRIVATE_KEY);
async function sendWebPush(subscription, payload) {
  try {
    await webpush.sendNotification(subscription, JSON.stringify(payload));
    return true;
  } catch (err) {
    if (err.statusCode === 410) console.warn('[WebPush] Subscription expirée — à supprimer');
    else console.error('[WebPush] Erreur:', err.message);
    return false;
  }
}

const { initializeApp, cert } = require('firebase-admin/app');
const { getMessaging } = require('firebase-admin/messaging');
async function sendFCMPush(token, notification, data = {}) {
  const message = {
    token,
    notification: { title: notification.title, body: notification.body, ...(notification.imageUrl && { imageUrl: notification.imageUrl }) },
    data: Object.fromEntries(Object.entries(data).map(([k,v]) => [k, String(v)])),
