const Redis = require('ioredis');
const redis = new Redis(REDIS_URL);
async function cacheGet(key, defaultValue = null) {
  try {
    const raw = await redis.get(key);
    if (raw === null) return defaultValue;
    try { return JSON.parse(raw); } catch { return raw; }
  } catch (err) {
    console.error(`[Cache] GET ${key} failed:`, err.message);
    return defaultValue;
  }
}

async function cacheSet(key, value, ttlSeconds = 3600) {
  try {
    const serialized = typeof value === 'string' ? value : JSON.stringify(value);
    if (ttlSeconds > 0) await redis.set(key, serialized, 'EX', ttlSeconds);
    else await redis.set(key, serialized);
    return true;
  } catch (err) {
    console.error(`[Cache] SET ${key} failed:`, err.message);
    return false;
  }
}

async function cacheOrFetch(key, fetchFn, ttlSeconds = 300) {
  const cached = await cacheGet(key);
  if (cached !== null) return cached;
  const fresh = await fetchFn();
  await cacheSet(key, fresh, ttlSeconds);
  return fresh;
}

async function cacheDel(pattern) {
  if (!pattern.includes('*')) {
    return redis.del(pattern);
  }
  let cursor = '0', deleted = 0;
  do {
    const [newCursor, keys] = await redis.scan(cursor, 'MATCH', pattern, 'COUNT', 100);
    cursor = newCursor;
    if (keys.length) deleted += await redis.del(...keys);
  } while (cursor !== '0');
  return deleted;
}

async function redisPublish(channel, message) {
  const payload = typeof message === 'string' ? message : JSON.stringify(message);
  return redis.publish(channel, payload);
}

const Redis = require('ioredis');
function redisSubscribe(channels, handler) {
  const sub = new Redis(REDIS_URL);
  sub.subscribe(...channels);
  sub.on('message', (channel, raw) => {
    try { handler(channel, JSON.parse(raw)); }
    catch { handler(channel, raw); }
  });
  return sub;
}

const { S3Client, PutObjectCommand } = require('@aws-sdk/client-s3');
const s3 = new S3Client({ region: S3_REGION });
async function uploadToS3(key, body, contentType = 'application/octet-stream', acl = 'private', metadata = {}) {
  const cmd = new PutObjectCommand({
    Bucket: S3_BUCKET, Key: key, Body: body,
    ContentType: contentType, ACL: acl, Metadata: metadata
  });
  const res = await s3.send(cmd);
  const url = `https://${S3_BUCKET}.s3.${S3_REGION}.amazonaws.com/${key}`;
  console.log(`[S3] Upload OK: ${key} (ETag: ${res.ETag})`);
  return { url, key, etag: res.ETag };
}

const { GetObjectCommand } = require('@aws-sdk/client-s3');
const { getSignedUrl } = require('@aws-sdk/s3-request-presigner');
async function getSignedS3URL(key, expiresInSeconds = 3600) {
  const cmd = new GetObjectCommand({ Bucket: S3_BUCKET, Key: key });
  return getSignedUrl(s3, cmd, { expiresIn: expiresInSeconds });
}

const { DeleteObjectCommand } = require('@aws-sdk/client-s3');
async function deleteS3Object(key) {
  try {
    await s3.send(new DeleteObjectCommand({ Bucket: S3_BUCKET, Key: key }));
    console.log(`[S3] Objet supprimé : ${key}`);
    return true;
  } catch (err) {
    console.error(`[S3] Erreur suppression ${key}:`, err.message);
    return false;
  }
}

const amqplib = require('amqplib');
async function publishToQueue(queueName, message, options = {}) {
  const conn = await amqplib.connect(RABBITMQ_URL);
  const ch = await conn.createChannel();
  await ch.assertQueue(queueName, { durable: true });
  const payload = Buffer.from(JSON.stringify(message));
  const ok = ch.sendToQueue(queueName, payload, {
    persistent: true,
    contentType: 'application/json',
    ...options
  });
  await ch.close();
  await conn.close();
  return ok;
}

const amqplib = require('amqplib');
async function consumeQueue(queueName, handler, prefetch = 10) {
  const conn = await amqplib.connect(RABBITMQ_URL);
  const ch = await conn.createChannel();
  await ch.assertQueue(queueName, { durable: true });
  ch.prefetch(prefetch);
  console.log(`[RabbitMQ] Écoute de ${queueName}...`);
  ch.consume(queueName, async (msg) => {
    if (!msg) return;
    try {
      const data = JSON.parse(msg.content.toString());
      await handler(data);
      ch.ack(msg);
    } catch (err) {
      console.error(`[RabbitMQ] Erreur handler ${queueName}:`, err.message);
      ch.nack(msg, false, false); // dead-letter
    }
  });
}

const { Kafka } = require('kafkajs');
const kafka = new Kafka({ clientId: 'myapp', brokers: KAFKA_BROKERS });
async function publishKafkaMessage(topic, message, key = null, headers = {}) {
  const producer = kafka.producer();
  await producer.connect();
  const msgs = [{ value: JSON.stringify(message), ...(key && { key }), headers }];
  const res = await producer.send({ topic, messages: msgs });
  await producer.disconnect();
  const { partition, offset } = res[0].topicPartitions?.[0] ?? {};
  console.log(`[Kafka] Publié sur ${topic} | partition=${partition} offset=${offset}`);
  return { partition, offset };
}

const { Kafka } = require('kafkajs');
async function consumeKafkaTopic(topic, groupId, handler, fromBeginning = false) {
  const kafka = new Kafka({ clientId: 'myapp-consumer', brokers: KAFKA_BROKERS });
  const consumer = kafka.consumer({ groupId });
  await consumer.connect();
  await consumer.subscribe({ topic, fromBeginning });
  consumer.run({
    eachMessage: async ({ topic, partition, message }) => {
      try {
        const data = JSON.parse(message.value.toString());
        await handler(data, { topic, partition, offset: message.offset, headers: message.headers });
      } catch (err) {
        console.error(`[Kafka] Erreur consumer ${topic}:`, err.message);
      }
    }
  });
  return { disconnect: () => consumer.disconnect() };
}

const promClient = require('prom-client');
function setupPrometheusMetrics(app, customMetrics = []) {
  const register = new promClient.Registry();
  promClient.collectDefaultMetrics({ register });
  // Histogramme HTTP
  const httpDuration = new promClient.Histogram({
    name: 'http_request_duration_seconds',
    help: 'Durée des requêtes HTTP',
    labelNames: ['method', 'route', 'status_code'],
    buckets: [0.01, 0.05, 0.1, 0.3, 0.5, 1, 2, 5],
    registers: [register]
  });
  // Counter erreurs
  const httpErrors = new promClient.Counter({
    name: 'http_errors_total',
    help: 'Total des erreurs HTTP',
    labelNames: ['method', 'route', 'status_code'],
    registers: [register]
  });
  // Middleware timing
  app.use((req, res, next) => {
    const end = httpDuration.startTimer({ method: req.method, route: req.route?.path || req.path });
    res.on('finish', () => {
      end({ status_code: res.statusCode });
      if (res.statusCode >= 400) httpErrors.inc({ method: req.method, route: req.path, status_code: res.statusCode });
    });
    next();
  });
  // Métriques custom
  const instances = {};
  customMetrics.forEach(m => {
    const MetricClass = { counter: promClient.Counter, gauge: promClient.Gauge, histogram: promClient.Histogram }[m.type] || promClient.Counter;
    instances[m.name] = new MetricClass({ name: m.name, help: m.help, labelNames: m.labels || [], registers: [register] });
  });
  app.get('/metrics', async (req, res) => { res.set('Content-Type', register.contentType); res.end(await register.metrics()); });
  return { register, metrics: { httpDuration, httpErrors, ...instances } };
}

const Sentry = require('@sentry/node');
function setupSentry(dsn = SENTRY_DSN, environment = process.env.NODE_ENV, tracesSampleRate = 0.1) {
  Sentry.init({
    dsn, environment, tracesSampleRate,
    integrations: [new Sentry.Integrations.Http({ tracing: true })],
    beforeSend(event) {
      // Filtrer données sensibles
      if (event.request?.data) {
        const sensitive = ['password', 'token', 'secret', 'credit_card', 'ssn'];
        sensitive.forEach(k => { if (event.request.data[k]) event.request.data[k] = '[REDACTED]'; });
      }
      return event;
    }
  });
  console.log(`[Sentry] Initialisé — env: ${environment}, sample: ${tracesSampleRate}`);
}

const pino = require('pino');
function createStructuredLogger(level = 'info', pretty = false, logFile = null) {
  const transports = [];
  if (pretty && process.env.NODE_ENV !== 'production') {
    transports.push({ target: 'pino-pretty', options: { colorize: true, translateTime: 'SYS:standard', ignore: 'pid,hostname' } });
  } else {
    transports.push({ target: 'pino/file', options: { destination: 1 } }); // stdout
  }
  if (logFile) {
    transports.push({ target: 'pino-roll', options: { file: logFile, frequency: 'daily', limit: { count: 7 }, mkdir: true } });
  }
  return pino({
    level,
    timestamp: pino.stdTimeFunctions.isoTime,
    base: { env: process.env.NODE_ENV, version: process.env.npm_package_version },
    redact: { paths: ['req.headers.authorization', 'body.password', 'body.token'], censor: '[REDACTED]' },
    transport: { targets: transports }
  });
}

