async function queryPrometheus(query, type = 'instant', range = null) {
  let url;
  if (type === 'range' && range) {
    const params = new URLSearchParams({ query, start: range.start, end: range.end, step: range.step });
    url = `${PROMETHEUS_URL}/api/v1/query_range?${params}`;
  } else {
    url = `${PROMETHEUS_URL}/api/v1/query?query=${encodeURIComponent(query)}`;
  }
