const { ethers } = require('ethers');
const ERC20_ABI = ['function balanceOf(address) view returns (uint256)', 'function decimals() view returns (uint8)', 'function symbol() view returns (string)'];
async function getEthBalance(address, tokenAddresses = [], rpcUrl = ETH_RPC_URL) {
  const provider = new ethers.JsonRpcProvider(rpcUrl);
  const ethBalance = ethers.formatEther(await provider.getBalance(address));
  const tokens = await Promise.all(tokenAddresses.map(async (addr) => {
    const contract = new ethers.Contract(addr, ERC20_ABI, provider);
    const [balance, decimals, symbol] = await Promise.all([contract.balanceOf(address), contract.decimals(), contract.symbol()]);
    return { address: addr, symbol, balance: ethers.formatUnits(balance, decimals) };
  }));
  return { eth: ethBalance, tokens };
}

const { ethers } = require('ethers');
async function sendEthTransaction(to, amountEth, signer, maxGasGwei = MAX_GAS_PRICE_GWEI) {
  const provider = signer.provider;
  const feeData = await provider.getFeeData();
  const gasPriceGwei = Number(ethers.formatUnits(feeData.gasPrice, 'gwei'));
  if (gasPriceGwei > maxGasGwei) throw new Error(`Gas price trop élevé: ${gasPriceGwei.toFixed(1)} Gwei (max: ${maxGasGwei})`);
  const tx = await signer.sendTransaction({
    to,
    value: ethers.parseEther(amountEth),
    maxFeePerGas: feeData.maxFeePerGas,
    maxPriorityFeePerGas: feeData.maxPriorityFeePerGas
  });
  console.log(`[Web3] Tx envoyée: ${tx.hash}`);
  const receipt = await tx.wait(1);
  console.log(`[Web3] Tx confirmée: block ${receipt.blockNumber} | gas: ${receipt.gasUsed}`);
  return { hash: tx.hash, receipt };
}

const { ethers } = require('ethers');
async function callSmartContract(contractAddress, abi, functionName, args = [], signerOrProvider) {
  const contract = new ethers.Contract(contractAddress, abi, signerOrProvider);
  if (!contract[functionName]) throw new Error(`Fonction '${functionName}' introuvable dans l'ABI`);
  const result = await contract[functionName](...args);
  // Si c'est une transaction (write), attendre la confirmation
  if (result?.wait) {
    console.log(`[Web3] Tx ${functionName}: ${result.hash}`);
    const receipt = await result.wait(1);
    return { hash: result.hash, receipt, events: receipt.logs };
  }
  return result;
}

const { ethers } = require('ethers');
function listenToContractEvents(contractAddress, abi, eventName, handler, filterArgs = []) {
  const provider = new ethers.JsonRpcProvider(ETH_RPC_URL);
  const contract = new ethers.Contract(contractAddress, abi, provider);
  const filter = contract.filters[eventName]?.(...filterArgs);
  if (!filter) throw new Error(`Event '${eventName}' introuvable`);
  const wrappedHandler = (...args) => {
    const event = args[args.length - 1];
    console.log(`[Web3] Event ${eventName} @ block ${event.log?.blockNumber}`);
    handler(...args);
  };
  contract.on(filter, wrappedHandler);
  console.log(`[Web3] Écoute event: ${eventName} sur ${contractAddress}`);
  return { unsubscribe: () => contract.off(filter, wrappedHandler) };
}

const { ethers } = require('ethers');
const fs = require('fs');
async function deploySolidityContract(artifactPath, constructorArgs = [], signer) {
  const artifact = JSON.parse(fs.readFileSync(artifactPath, 'utf8'));
  const factory = new ethers.ContractFactory(artifact.abi, artifact.bytecode, signer);
  const feeData = await signer.provider.getFeeData();
  const gasPriceGwei = Number(ethers.formatUnits(feeData.gasPrice, 'gwei'));
  if (gasPriceGwei > MAX_GAS_PRICE_GWEI) throw new Error(`Gas trop élevé: ${gasPriceGwei} Gwei`);
  console.log(`[Solidity] Déploiement de ${artifact.contractName}...`);
  const contract = await factory.deploy(...constructorArgs);
  const receipt = await contract.deploymentTransaction().wait(1);
  const address = await contract.getAddress();
  console.log(`[Solidity] ✅ Déployé: ${address} | Block: ${receipt.blockNumber}`);
  return { address, hash: receipt.hash, blockNumber: receipt.blockNumber, abi: artifact.abi };
}

