contract MyNFT is ERC721URIStorage, ERC721Royalty, Ownable {
    using Counters for Counters.Counter;
    Counters.Counter private _tokenIds;

    uint256 public constant MAX_SUPPLY = 10_000;
    uint256 public mintPrice = 0.05 ether;
    bool public publicMintEnabled = false;
    bytes32 public merkleRoot;
    string public baseURI;

    event NFTMinted(address indexed to, uint256 tokenId, string tokenURI);

    constructor(string memory name, string memory symbol, address royaltyRecipient, uint96 royaltyBps)
        ERC721(name, symbol) Ownable(msg.sender) {
        _setDefaultRoyalty(royaltyRecipient, royaltyBps); // ex: 500 = 5%
    }

    function whitelistMint(string memory tokenURI, bytes32[] calldata proof) external payable {
        require(msg.value >= mintPrice, "Prix insuffisant");
        bytes32 leaf = keccak256(abi.encodePacked(msg.sender));
        require(MerkleProof.verify(proof, merkleRoot, leaf), "Non whitelisté");
        _mintNFT(msg.sender, tokenURI);
    }

    function publicMint(string memory tokenURI) external payable {
        require(publicMintEnabled, "Mint public desactive");
        require(msg.value >= mintPrice, "Prix insuffisant");
