pragma solidity ^0.8.24;

contract MultiSigWallet {
    event Deposit(address indexed sender, uint amount);
    event SubmitTransaction(address indexed owner, uint indexed txIndex, address indexed to, uint value, bytes data);
    event ConfirmTransaction(address indexed owner, uint indexed txIndex);
    event RevokeConfirmation(address indexed owner, uint indexed txIndex);
    event ExecuteTransaction(address indexed owner, uint indexed txIndex);

    address[] public owners;
    mapping(address => bool) public isOwner;
    uint public numConfirmationsRequired;

    struct Transaction {
        address to;
        uint value;
        bytes data;
        bool executed;
        uint numConfirmations;
    }
    Transaction[] public transactions;
    mapping(uint => mapping(address => bool)) public isConfirmed;

    modifier onlyOwner() { require(isOwner[msg.sender], "Not owner"); _; }
    modifier txExists(uint i) { require(i < transactions.length, "tx not exists"); _; }
    modifier notExecuted(uint i) { require(!transactions[i].executed, "already executed"); _; }
    modifier notConfirmed(uint i) { require(!isConfirmed[i][msg.sender], "already confirmed"); _; }

    constructor(address[] memory _owners, uint _required) {
        require(_owners.length > 0 && _required > 0 && _required <= _owners.length, "Invalid params");
        for (uint i = 0; i < _owners.length; i++) {
            require(!isOwner[_owners[i]] && _owners[i] != address(0), "Invalid owner");
            isOwner[_owners[i]] = true;
            owners.push(_owners[i]);
        }
        numConfirmationsRequired = _required;
    }

    receive() external payable { emit Deposit(msg.sender, msg.value); }

    function submitTransaction(address to, uint value, bytes calldata data) external onlyOwner {
        transactions.push(Transaction({ to: to, value: value, data: data, executed: false, numConfirmations: 0 }));
        emit SubmitTransaction(msg.sender, transactions.length - 1, to, value, data);
    }

    function confirmTransaction(uint txIndex) external onlyOwner txExists(txIndex) notExecuted(txIndex) notConfirmed(txIndex) {
        transactions[txIndex].numConfirmations++;
        isConfirmed[txIndex][msg.sender] = true;
        emit ConfirmTransaction(msg.sender, txIndex);
    }

    function executeTransaction(uint txIndex) external onlyOwner txExists(txIndex) notExecuted(txIndex) {
        Transaction storage t = transactions[txIndex];
        require(t.numConfirmations >= numConfirmationsRequired, "Insufficient confirmations");
        t.executed = true;
        (bool success, ) = t.to.call{value: t.value}(t.data);
        require(success, "Tx failed");
        emit ExecuteTransaction(msg.sender, txIndex);
    }

    function revokeConfirmation(uint txIndex) external onlyOwner txExists(txIndex) notExecuted(txIndex) {
        require(isConfirmed[txIndex][msg.sender], "Not confirmed");
        transactions[txIndex].numConfirmations--;
        isConfirmed[txIndex][msg.sender] = false;
        emit RevokeConfirmation(msg.sender, txIndex);
    }
}

