pragma solidity ^0.8.24;

import "@chainlink/contracts/src/v0.8/interfaces/AggregatorV3Interface.sol";

contract PriceFeedConsumer {
    AggregatorV3Interface public immutable priceFeed;
    uint256 public constant STALENESS_THRESHOLD = 3600; // 1 heure
    int256 public constant CIRCUIT_BREAKER_MIN = 100 * 1e8; // $100
    int256 public constant CIRCUIT_BREAKER_MAX = 1_000_000 * 1e8; // $1M

    error StalePriceFeed(uint256 updatedAt, uint256 threshold);
    error PriceOutOfRange(int256 price);
    error InvalidPrice();

    constructor(address feedAddress) {
        priceFeed = AggregatorV3Interface(feedAddress);
    }

    function getLatestPrice() public view returns (int256 price, uint256 timestamp) {
        (
            uint80 roundId,
            int256 answer,
            ,
            uint256 updatedAt,
            uint80 answeredInRound
        ) = priceFeed.latestRoundData();

        require(answeredInRound >= roundId, "Stale round");
        if (answer <= 0) revert InvalidPrice();
        if (block.timestamp - updatedAt > STALENESS_THRESHOLD)
            revert StalePriceFeed(updatedAt, STALENESS_THRESHOLD);
        if (answer < CIRCUIT_BREAKER_MIN || answer > CIRCUIT_BREAKER_MAX)
            revert PriceOutOfRange(answer);

        return (answer, updatedAt);
    }

    function getPriceInUSD() external view returns (uint256) {
        (int256 price, ) = getLatestPrice();
        uint8 decimals = priceFeed.decimals();
        return uint256(price) * 1e18 / (10 ** decimals);
    }
}

const FormData = require('form-data');
async function uploadToIPFS(content, filename = 'upload', isMetadata = false) {
  let body, endpoint, headers;
  const baseUrl = 'https://api.pinata.cloud';
  const authHeaders = { Authorization: `Bearer ${PINATA_API_KEY}` };
  if (isMetadata || typeof content === 'object' && !Buffer.isBuffer(content)) {
    endpoint = `${baseUrl}/pinning/pinJSONToIPFS`;
    body = JSON.stringify({ pinataContent: content, pinataMetadata: { name: filename } });
    headers = { ...authHeaders, 'Content-Type': 'application/json' };
  } else {
    endpoint = `${baseUrl}/pinning/pinFileToIPFS`;
    const form = new FormData();
    form.append('file', Buffer.isBuffer(content) ? content : Buffer.from(content), filename);
    form.append('pinataMetadata', JSON.stringify({ name: filename }));
    body = form;
    headers = { ...authHeaders, ...form.getHeaders() };
  }
  const res = await fetch(endpoint, { method: 'POST', headers, body });
  if (!res.ok) throw new Error(`Pinata error: ${res.statusText}`);
  const data = await res.json();
  const cid = data.IpfsHash;
  return { cid, url: `ipfs://${cid}`, gatewayUrl: `${IPFS_GATEWAY}${cid}` };
}

