const { ethers } = require('ethers');
const SWAP_ROUTER_ABI = [
  'function exactInputSingle((address tokenIn, address tokenOut, uint24 fee, address recipient, uint256 deadline, uint256 amountIn, uint256 amountOutMinimum, uint160 sqrtPriceLimitX96)) external payable returns (uint256 amountOut)',
  'function quoteExactInputSingle(address tokenIn, address tokenOut, uint24 fee, uint256 amountIn, uint160 sqrtPriceLimitX96) external returns (uint256 amountOut)'
];
const ERC20_ABI_MIN = ['function approve(address,uint256) returns (bool)', 'function decimals() view returns (uint8)'];
async function swapTokensUniswapV3(tokenIn, tokenOut, amountIn, slippagePct = 0.5, fee = 3000, signer) {
  const router = new ethers.Contract(UNISWAP_V3_ROUTER, SWAP_ROUTER_ABI, signer);
  const tokenInContract = new ethers.Contract(tokenIn, ERC20_ABI_MIN, signer);
  const decimals = await tokenInContract.decimals();
  const amountInWei = ethers.parseUnits(amountIn, decimals);
  // Approve
  await (await tokenInContract.approve(UNISWAP_V3_ROUTER, amountInWei)).wait();
  const deadline = Math.floor(Date.now() / 1000) + 60 * 20;
  const slippageFactor = BigInt(Math.floor((1 - slippagePct / 100) * 10000));
  // Estimate amountOutMinimum à 0 pour simplicité (en prod: utiliser quoter)
  const params = { tokenIn, tokenOut, fee, recipient: await signer.getAddress(), deadline, amountIn: amountInWei, amountOutMinimum: 0n, sqrtPriceLimitX96: 0n };
  const tx = await router.exactInputSingle(params);
  const receipt = await tx.wait();
  console.log(`[DeFi] Swap exécuté | Hash: ${tx.hash} | Gas: ${receipt.gasUsed}`);
  return { hash: tx.hash, receipt };
}

async function getDeFiProtocolStats(protocol, chain = 'Ethereum') {
  const [tvlRes, volRes] = await Promise.allSettled([
    fetchWithRetry(`https://api.llama.fi/protocol/${protocol}`),
    fetchWithRetry(`https://api.llama.fi/summary/dexs/${protocol}?dataType=dailyVolume`)
  ]);
  const tvlData = tvlRes.status === 'fulfilled' ? tvlRes.value : null;
  const volData = volRes.status === 'fulfilled' ? volRes.value : null;
  const chainTVL = tvlData?.chainTvls?.[chain];
  const tvls = chainTVL?.tvl || tvlData?.tvl || [];
  const currentTVL = tvls[tvls.length - 1]?.totalLiquidityUSD || 0;
  const prevTVL = tvls[tvls.length - 2]?.totalLiquidityUSD || 0;
  const change24h = prevTVL > 0 ? ((currentTVL - prevTVL) / prevTVL) * 100 : 0;
  return {
    protocol,
    chain,
    tvl: currentTVL,
    tvlFormatted: `$${(currentTVL / 1e9).toFixed(2)}B`,
    change24h: change24h.toFixed(2) + '%',
    volume24h: volData?.totalDataChart?.slice(-1)?.[0]?.[1] || 0
  };
}

