const { ethers } = require('ethers');
async function getGasPrice(rpcUrl = ETH_RPC_URL) {
  const provider = new ethers.JsonRpcProvider(rpcUrl);
  const feeData = await provider.getFeeData();
  const block = await provider.getBlock('latest');
  const baseFeeGwei = Number(ethers.formatUnits(block.baseFeePerGas || feeData.gasPrice, 'gwei'));
  const priorityFeeGwei = Number(ethers.formatUnits(feeData.maxPriorityFeePerGas || ethers.parseGwei('1'), 'gwei'));
  return {
    baseFee: baseFeeGwei.toFixed(2),
    slow:     (baseFeeGwei * 1.05).toFixed(2),
    standard: (baseFeeGwei * 1.10 + priorityFeeGwei).toFixed(2),
    fast:     (baseFeeGwei * 1.25 + priorityFeeGwei * 2).toFixed(2),
    unit: 'Gwei'
  };
}

const { ethers } = require('ethers');
async function decodeTransactionInput(txHash, abi, rpcUrl = ETH_RPC_URL) {
  const provider = new ethers.JsonRpcProvider(rpcUrl);
  const tx = await provider.getTransaction(txHash);
  if (!tx?.data || tx.data === '0x') throw new Error('Pas de données input dans la transaction');
  const iface = new ethers.Interface(abi);
  const decoded = iface.parseTransaction({ data: tx.data, value: tx.value });
  if (!decoded) throw new Error('Impossible de décoder la transaction avec cet ABI');
  const args = {};
  decoded.fragment.inputs.forEach((input, i) => { args[input.name || i] = decoded.args[i]; });
  return { functionName: decoded.name, args, signature: decoded.signature, value: ethers.formatEther(tx.value) };
}

const { ethers } = require('ethers');
function monitorMempoolTransactions(targetAddress, handler, wsRpcUrl = process.env.ETH_WS_URL) {
  const provider = new ethers.WebSocketProvider(wsRpcUrl);
  const normalizedTarget = targetAddress.toLowerCase();
  provider.on('pending', async (txHash) => {
    try {
      const tx = await provider.getTransaction(txHash);
      if (!tx) return;
      if (tx.to?.toLowerCase() === normalizedTarget) {
        console.log(`[Mempool] Tx vers ${targetAddress}: ${txHash}`);
        handler(tx);
      }
    } catch { /* ignorer les tx non trouvées */ }
  });
  console.log(`[Mempool] Surveillance active: ${targetAddress}`);
  return { stop: () => provider.destroy() };
}

const express = require('express');
const helmet = require('helmet');
const compression = require('compression');
const { v4: uuidv4 } = require('uuid');
function setupExpressServer(port = 3000, options = {}) {
  const app = express();
  const logger = createStructuredLogger(process.env.LOG_LEVEL || 'info', process.env.NODE_ENV !== 'production');
  // Sécurité
  app.use(helmet({ contentSecurityPolicy: { directives: { defaultSrc: ["'self'"], scriptSrc: ["'self'"] } } }));
  app.use(compression());
  app.use(express.json({ limit: '10mb' }));
  app.use(express.urlencoded({ extended: true }));
  // Request ID
  app.use((req, res, next) => { req.id = uuidv4(); res.setHeader('X-Request-ID', req.id); next(); });
  // CORS
  if (options.cors !== false) app.use(corsMiddleware());
  // Rate limit
  if (options.rateLimit !== false) app.use(rateLimitMiddleware());
  // Prometheus
  setupPrometheusMetrics(app);
  // Health check
  app.get('/health', (req, res) => res.json({ status: 'ok', uptime: process.uptime(), timestamp: new Date().toISOString() }));
  app.get('/ready', async (req, res) => {
    try {
      await redis.ping();
      res.json({ status: 'ready' });
    } catch { res.status(503).json({ status: 'not ready', error: 'Redis unreachable' }); }
  });
  // Error handler
  app.use((err, req, res, next) => {
    logger.error({ err, requestId: req.id }, err.message);
    res.status(err.status || 500).json({ error: err.message || 'Internal Server Error', requestId: req.id });
  });
  const server = app.listen(port, () => logger.info(`🚀 Server running on port ${port}`));
  // Graceful shutdown
  ['SIGTERM', 'SIGINT'].forEach(sig => process.on(sig, () => {
    logger.info(`${sig} received — graceful shutdown...`);
    server.close(() => { redis.quit(); process.exit(0); });
    setTimeout(() => process.exit(1), 10000);
  }));
  return { app, server, logger };
}

import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { createApiClient } from './apiClient';

const api = createApiClient(API_BASE_URL, () => localStorage.getItem('token'));

export function useApiQuery<T>(endpoint: string, options: any = {}) {
  return useQuery<T>({
    queryKey: [endpoint],
    queryFn: () => api.get(endpoint),
    staleTime: 5 * 60 * 1000, // 5 min
    retry: (failureCount, error: any) => error?.message !== 'TOKEN_EXPIRED' && failureCount < 3,
    ...options
  });
}

export function useApiMutation<TData, TVariables>(endpoint: string, method: 'post' | 'put' | 'patch' | 'delete' = 'post') {
  const queryClient = useQueryClient();
  return useMutation<TData, Error, TVariables>({
    mutationFn: (data: TVariables) => api[method](endpoint, data),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: [endpoint] }),
    onError: (error) => console.error(`[Mutation] ${endpoint}:`, error.message)
  });
}

export function usePaginatedQuery<T>(endpoint: string, page: number, pageSize: number = 20) {
  return useQuery<{ data: T[], total: number, pages: number }>({
    queryKey: [endpoint, page, pageSize],
    queryFn: () => api.get(`${endpoint}?page=${page}&limit=${pageSize}`),
    placeholderData: (prev) => prev,
    staleTime: 60 * 1000
  });
}

import { useState, useEffect, useRef, useCallback } from 'react';

export function useWebSocket(url: string, onMessage?: (data: any) => void, enabled: boolean = true) {
  const [isConnected, setIsConnected] = useState(false);
  const [lastMessage, setLastMessage] = useState<any>(null);
  const wsRef = useRef<WebSocket | null>(null);
  const reconnectRef = useRef<ReturnType<typeof setTimeout>>();
  const mountedRef = useRef(true);

  const connect = useCallback(() => {
    if (!enabled || !mountedRef.current) return;
    const ws = new WebSocket(url);
    ws.onopen = () => { if (mountedRef.current) setIsConnected(true); };
    ws.onclose = () => {
      if (mountedRef.current) {
        setIsConnected(false);
        reconnectRef.current = setTimeout(connect, 3000);
      }
    };
    ws.onmessage = (e) => {
      try {
        const data = JSON.parse(e.data);
        setLastMessage(data);
        onMessage?.(data);
      } catch { onMessage?.(e.data); }
    };
    wsRef.current = ws;
  }, [url, enabled, onMessage]);

  useEffect(() => {
    mountedRef.current = true;
    connect();
    return () => {
      mountedRef.current = false;
      clearTimeout(reconnectRef.current);
      wsRef.current?.close();
    };
  }, [connect]);

  const send = useCallback((data: any) => {
    if (wsRef.current?.readyState === WebSocket.OPEN)
      wsRef.current.send(JSON.stringify(data));
  }, []);

  return { isConnected, send, lastMessage };
}

import { useState, useEffect, useCallback } from 'react';
import { ethers } from 'ethers';

export function useWeb3Wallet() {
  const [address, setAddress] = useState<string | null>(null);
  const [chainId, setChainId] = useState<number | null>(null);
  const [balance, setBalance] = useState<string>('0');
  const [isConnecting, setIsConnecting] = useState(false);

  const isConnected = !!address;

  const fetchBalance = useCallback(async (addr: string) => {
    if (!window.ethereum) return;
    const provider = new ethers.BrowserProvider(window.ethereum);
    const bal = await provider.getBalance(addr);
    setBalance(ethers.formatEther(bal));
  }, []);

  useEffect(() => {
    if (!window.ethereum) return;
    const handleAccountsChanged = (accounts: string[]) => {
      setAddress(accounts[0] || null);
      if (accounts[0]) fetchBalance(accounts[0]);
    };
    const handleChainChanged = (chainId: string) => setChainId(parseInt(chainId, 16));
    window.ethereum.on('accountsChanged', handleAccountsChanged);
    window.ethereum.on('chainChanged', handleChainChanged);
    return () => {
      window.ethereum.removeListener('accountsChanged', handleAccountsChanged);
      window.ethereum.removeListener('chainChanged', handleChainChanged);
    };
  }, [fetchBalance]);

  const connect = useCallback(async () => {
    if (!window.ethereum) throw new Error('MetaMask non installé');
    setIsConnecting(true);
    try {
      const { address, chainId } = await connectWallet('injected', ETH_CHAIN_ID);
      setAddress(address);
      setChainId(chainId);
      await fetchBalance(address);
    } finally { setIsConnecting(false); }
  }, [fetchBalance]);

  const disconnect = useCallback(() => { setAddress(null); setChainId(null); setBalance('0'); }, []);

  return { address, chainId, balance, isConnected, isConnecting, connect, disconnect };
}

