import { PrismaClient, Prisma } from '@prisma/client';

const globalForPrisma = globalThis as unknown as { prisma: PrismaClient };

function setupPrismaClient(): PrismaClient {
  const prisma = new PrismaClient({
    log: process.env.NODE_ENV === 'development'
      ? [{ level: 'query', emit: 'event' }, 'warn', 'error']
      : ['warn', 'error'],
    errorFormat: 'pretty'
  });

  // Log query performance en dev
  if (process.env.NODE_ENV === 'development') {
    (prisma as any).$on('query', (e: Prisma.QueryEvent) => {
      if (e.duration > 100) console.warn(`[Prisma] Slow query (${e.duration}ms): ${e.query.substring(0, 100)}...`);
    });
  }

  // Middleware soft-delete
  prisma.$use(async (params, next) => {
    const softDeleteModels = ['User', 'Post', 'Product'];
    if (softDeleteModels.includes(params.model || '')) {
      if (params.action === 'delete') {
        params.action = 'update';
        params.args.data = { deletedAt: new Date() };
      }
      if (params.action === 'findMany' || params.action === 'findFirst') {
        params.args.where = { ...params.args.where, deletedAt: null };
      }
    }
    return next(params);
  });

  return prisma;
}

