const { Client } = require('@elastic/elasticsearch');
const esClient = new Client({ node: process.env.ELASTICSEARCH_URL || 'http://localhost:9200' });
async function elasticsearchIndex(indexName, documents, idField = 'id') {
  if (!documents.length) return { indexed: 0, errors: [] };
  const operations = documents.flatMap(doc => [
    { index: { _index: indexName, _id: doc[idField] } },
    doc
  ]);
  const { items } = await esClient.bulk({ refresh: true, operations });
  const errors = items.filter(item => item.index?.error).map(item => item.index?.error);
  const indexed = items.length - errors.length;
  if (errors.length) console.warn(`[ES] ${errors.length} erreurs d'indexation sur ${items.length}`);
  console.log(`[ES] ${indexed} documents indexés dans ${indexName}`);
  return { indexed, errors };
}

