import React, { Component, ReactNode, ErrorInfo } from 'react';
import * as Sentry from '@sentry/react';

interface Props { children: ReactNode; fallback?: (error: Error, reset: () => void) => ReactNode; }
interface State { hasError: boolean; error: Error | null; }

export class ErrorBoundary extends Component<Props, State> {
  state: State = { hasError: false, error: null };

  static getDerivedStateFromError(error: Error): State {
    return { hasError: true, error };
  }

  componentDidCatch(error: Error, info: ErrorInfo): void {
    console.error('[ErrorBoundary]', error, info.componentStack);
    Sentry.captureException(error, { extra: { componentStack: info.componentStack } });
  }

  reset = (): void => this.setState({ hasError: false, error: null });

  render(): ReactNode {
    if (this.state.hasError && this.state.error) {
      if (this.props.fallback) return this.props.fallback(this.state.error, this.reset);
      return (
        <div className="flex flex-col items-center justify-center min-h-[200px] p-6 text-center">
          <div className="text-4xl mb-4">💥</div>
          <h2 className="text-xl font-bold text-red-600 mb-2">Une erreur est survenue</h2>
          <p className="text-gray-500 mb-4 text-sm">{this.state.error.message}</p>
          <button onClick={this.reset} className="px-4 py-2 bg-blue-600 text-white rounded hover:bg-blue-700">Réessayer</button>
        </div>
      );
    }
    return this.props.children;
  }
}

import { createContext, useContext, useState, useEffect, useCallback, ReactNode } from 'react';

interface AuthUser { id: string; email: string; role: string; }
interface AuthCtx { user: AuthUser | null; token: string | null; login: (email: string, password: string) => Promise<void>; logout: () => void; isAuthenticated: boolean; isLoading: boolean; }

const AuthContext = createContext<AuthCtx | null>(null);

export function AuthProvider({ children }: { children: ReactNode }) {
  const [user, setUser] = useState<AuthUser | null>(null);
  const [token, setToken] = useState<string | null>(() => localStorage.getItem('token'));
  const [isLoading, setIsLoading] = useState(true);

  const logout = useCallback(() => {
    setUser(null); setToken(null);
    localStorage.removeItem('token'); localStorage.removeItem('refreshToken');
  }, []);

  useEffect(() => {
    const storedToken = localStorage.getItem('token');
    if (!storedToken) { setIsLoading(false); return; }
    fetch(`${API_BASE_URL}/auth/me`, { headers: { Authorization: `Bearer ${storedToken}` } })
      .then(r => r.ok ? r.json() : Promise.reject())
      .then(data => { setUser(data.user); setToken(storedToken); })
      .catch(logout)
      .finally(() => setIsLoading(false));
  }, [logout]);

  const login = useCallback(async (email: string, password: string) => {
    const res = await fetch(`${API_BASE_URL}/auth/login`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ email, password }) });
    if (!res.ok) throw new Error('Identifiants invalides');
    const { user, accessToken, refreshToken } = await res.json();
    setUser(user); setToken(accessToken);
    localStorage.setItem('token', accessToken);
    localStorage.setItem('refreshToken', refreshToken);
  }, []);

  return <AuthContext.Provider value={{ user, token, login, logout, isAuthenticated: !!user, isLoading }}>{children}</AuthContext.Provider>;
}

export function useAuth(): AuthCtx {
  const ctx = useContext(AuthContext);
  if (!ctx) throw new Error('useAuth doit être utilisé dans AuthProvider');
  return ctx;
}

