import { create } from 'zustand';
import { devtools, persist, subscribeWithSelector } from 'zustand/middleware';
import { immer } from 'zustand/middleware/immer';

interface UserSlice { user: any; setUser: (u: any) => void; clearUser: () => void; }
interface UISlice { theme: 'light' | 'dark'; sidebarOpen: boolean; toggleTheme: () => void; setSidebar: (v: boolean) => void; }
interface Web3Slice { address: string | null; chainId: number | null; setWallet: (a: string, c: number) => void; clearWallet: () => void; }

type Store = UserSlice & UISlice & Web3Slice;

const useStore = create<Store>()(
  devtools(
    persist(
      subscribeWithSelector(
        immer((set) => ({
          // User slice
          user: null,
          setUser: (u) => set((s) => { s.user = u; }),
          clearUser: () => set((s) => { s.user = null; }),
          // UI slice
          theme: 'light' as const,
          sidebarOpen: true,
          toggleTheme: () => set((s) => { s.theme = s.theme === 'light' ? 'dark' : 'light'; }),
          setSidebar: (v) => set((s) => { s.sidebarOpen = v; }),
          // Web3 slice
          address: null,
          chainId: null,
          setWallet: (a, c) => set((s) => { s.address = a; s.chainId = c; }),
          clearWallet: () => set((s) => { s.address = null; s.chainId = null; })
        }))
      ),
      { name: 'app-store', partialize: (s) => ({ theme: s.theme, user: s.user }) }
    ),
    { name: 'AppStore' }
  )
);

export default useStore;

const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');
const secretCache = new Map();
async function createSecretsManager(secretName, provider = 'aws', cacheTtlMs = 300000) {
  const cacheKey = `${provider}:${secretName}`;
  const cached = secretCache.get(cacheKey);
  if (cached && Date.now() - cached.ts < cacheTtlMs) return cached.value;
  let secret;
  if (provider === 'aws') {
    const client = new SecretsManagerClient({ region: process.env.AWS_REGION });
    const res = await client.send(new GetSecretValueCommand({ SecretId: secretName }));
    secret = JSON.parse(res.SecretString || '{}');
  } else if (provider === 'vault') {
    const vaultToken = process.env.VAULT_TOKEN;
    const vaultUrl = process.env.VAULT_ADDR || 'http://vault:8200';
    const res = await fetch(`${vaultUrl}/v1/secret/data/${secretName}`, { headers: { 'X-Vault-Token': vaultToken } });
    const data = await res.json();
    secret = data.data?.data || {};
  } else {
    throw new Error(`Provider inconnu: ${provider}`);
  }
  secretCache.set(cacheKey, { value: secret, ts: Date.now() });
  return secret;
}

const crypto = require('crypto');
function setupWebhookVerification(payload, signature, secret, algorithm = 'sha256') {
  const rawSig = signature.startsWith(`${algorithm}=`) ? signature.slice(algorithm.length + 1) : signature;
  const expected = crypto.createHmac(algorithm, secret).update(payload).digest('hex');
  try {
    return crypto.timingSafeEqual(Buffer.from(rawSig, 'hex'), Buffer.from(expected, 'hex'));
  } catch {
    return false;
  }
}

const crypto = require('crypto');
function setupCSPHeaders(options = {}) {
  return (req, res, next) => {
    const nonce = options.nonce || crypto.randomBytes(16).toString('base64');
    res.locals.cspNonce = nonce;
    const directives = [
      `default-src 'self'`,
      `script-src 'self' 'nonce-${nonce}' 'strict-dynamic'`,
      `style-src 'self' 'nonce-${nonce}'`,
      `img-src 'self' data: https:`,
      `font-src 'self'`,
      `connect-src 'self' ${API_BASE_URL} wss:`,
      `frame-ancestors 'none'`,
      `base-uri 'self'`,
      `form-action 'self'`,
      `upgrade-insecure-requests`
    ];
    if (options.reportUri) directives.push(`report-uri ${options.reportUri}`);
    res.setHeader('Content-Security-Policy', directives.join('; '));
    res.setHeader('X-Frame-Options', 'DENY');
    res.setHeader('X-Content-Type-Options', 'nosniff');
    res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');
    res.setHeader('Permissions-Policy', 'camera=(), microphone=(), geolocation=()');
    next();
  };
}

