import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/cryptography/MerkleProof.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

contract CrossChainBridge is AccessControl, ReentrancyGuard {
    bytes32 public constant RELAYER_ROLE = keccak256("RELAYER_ROLE");
    bytes32 public constant ADMIN_ROLE = keccak256("ADMIN_ROLE");

    IERC20 public immutable token;
    uint256 public minAmount = 100e18;
    uint256 public bridgeFee = 30; // 0.3% en bps
    mapping(bytes32 => bool) public processedMessages;

    event TokensLocked(address indexed from, uint256 amount, uint256 targetChainId, bytes32 indexed messageId);
    event TokensReleased(address indexed to, uint256 amount, bytes32 indexed messageId);

    constructor(address _token) {
        token = IERC20(_token);
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(ADMIN_ROLE, msg.sender);
    }

    function lockTokens(uint256 amount, uint256 targetChainId, address targetAddress) external nonReentrant {
        require(amount >= minAmount, "Amount too small");
        uint256 fee = (amount * bridgeFee) / 10000;
        uint256 netAmount = amount - fee;
        token.transferFrom(msg.sender, address(this), amount);
        bytes32 messageId = keccak256(abi.encodePacked(msg.sender, amount, targetChainId, targetAddress, block.timestamp));
        emit TokensLocked(msg.sender, netAmount, targetChainId, messageId);
    }

    function releaseTokens(address to, uint256 amount, bytes32 messageId, bytes32[] calldata proof, bytes32 root)
        external onlyRole(RELAYER_ROLE) nonReentrant {
        require(!processedMessages[messageId], "Already processed");
        bytes32 leaf = keccak256(abi.encodePacked(to, amount, messageId));
        require(MerkleProof.verify(proof, root, leaf), "Invalid proof");
        processedMessages[messageId] = true;
        token.transfer(to, amount);
        emit TokensReleased(to, amount, messageId);
    }

    function setFee(uint256 newFee) external onlyRole(ADMIN_ROLE) {
        require(newFee <= 100, "Fee too high"); // max 1%
        bridgeFee = newFee;
    }
}

const { ethers } = require('ethers');
async function signTypedData(signer, domain, types, value) {
  const signature = await signer.signTypedData(domain, types, value);
  console.log(`[EIP-712] Signé par ${await signer.getAddress()} | sig: ${signature.slice(0,10)}...`);
  return signature;
}

// Exemple d'utilisation pour ERC-20 Permit :
async function signPermit(tokenAddress, signer, spender, amount, deadline) {
  const provider = signer.provider;
  const token = new ethers.Contract(tokenAddress, ['function nonces(address) view returns (uint256)', 'function name() view returns (string)', 'function version() view returns (string)'], provider);
  const [name, nonce, chainId] = await Promise.all([token.name(), token.nonces(await signer.getAddress()), (await provider.getNetwork()).chainId]);
  return signTypedData(signer,
    { name, version: '1', chainId: Number(chainId), verifyingContract: tokenAddress },
    { Permit: [{ name:'owner',type:'address' }, { name:'spender',type:'address' }, { name:'value',type:'uint256' }, { name:'nonce',type:'uint256' }, { name:'deadline',type:'uint256' }] },
    { owner: await signer.getAddress(), spender, value: amount, nonce, deadline }
  );
}
